#!/usr/bin/env bash
# Nightly off-provider copy of the irreplaceable objects (WP F13, docs/disaster-recovery.md).
#
# rclone sync of the user-uploaded objects - the keys under projects/*/userFiles/ - from the
# primary bucket (Cloudflare R2) to a bucket at a SECOND provider, so one provider losing an
# account, a region or an object set is not also the loss of the files a customer uploaded.
#
# What is deliberately NOT copied:
#   projects/*/outputFiles/ and projects/*/agentFiles/  render outputs and agent artifacts; they
#     are regenerated by re-running a workflow, and F10 deletes them on a per-plan schedule;
#   runner-staging/                                     transient upload staging (F5);
#   everything else                                     not project data.
# The database is a separate concern with its own backups: see docs/disaster-recovery.md.
#
# Configuration (all from the environment; none of it is a secret in this file):
#   BLOB_BACKUP_SOURCE    required. rclone path of the PRIMARY bucket root, for example
#                         reelbolt_primary:reelbolt-prod-objects (an rclone remote, or a local path)
#   BLOB_BACKUP_TARGET    required. rclone path of the SECOND-provider bucket, for example
#                         reelbolt_backup:reelbolt-prod-objects
#   RCLONE_CONFIG         optional. rclone config file (default /opt/reelbolt/rclone.conf)
#   BLOB_BACKUP_INCLUDE   optional. rclone filter (default /projects/*/userFiles/**)
#   BLOB_BACKUP_LOG_DIR   optional. Where the run log lives (default /var/log/reelbolt)
#   BLOB_BACKUP_RCLONE_LOG optional. The same log as rclone sees it, when rclone does not run on
#                         this host (RCLONE_BIN in a container; default: BLOB_BACKUP_LOG_DIR as-is)
#   BLOB_BACKUP_TRANSFERS optional. Parallel transfers (default 4)
#   BLOB_BACKUP_DRY_RUN   optional. true lists what would move without moving it
#   BLOB_BACKUP_VERIFY    optional. false skips the after-copy size comparison (default true)
#   RCLONE_BIN            optional. rclone command prefix (default rclone). The restore drill
#                         points it at a container; a cloud host uses the installed binary.
#
#   --restore             copy the OTHER way: from BLOB_BACKUP_TARGET back into
#                         BLOB_BACKUP_SOURCE. This is the object half of a disaster recovery, and it
#                         is the same script on purpose, so the filter and the verification cannot
#                         drift between taking the copy and putting it back.
#   --dry-run             list what would move, move nothing.
#
# Exit status: 0 only when the copy ran AND both sides hold the same object count and byte total.
# Safe to run twice: sync is idempotent, and an interrupted night resumes on the next one.

set -euo pipefail

# Required, but read leniently so --help works with nothing configured; the checks below refuse
# a run that is missing either one. Not readonly: --restore swaps them.
source_path="${BLOB_BACKUP_SOURCE:-}"
target_path="${BLOB_BACKUP_TARGET:-}"
readonly include_filter="${BLOB_BACKUP_INCLUDE:-/projects/*/userFiles/**}"
readonly log_dir="${BLOB_BACKUP_LOG_DIR:-/var/log/reelbolt}"
readonly transfers="${BLOB_BACKUP_TRANSFERS:-4}"
readonly verify="${BLOB_BACKUP_VERIFY:-true}"
readonly rclone_bin="${RCLONE_BIN:-rclone}"
readonly config="${RCLONE_CONFIG:-/opt/reelbolt/rclone.conf}"

usage() {
  sed -n '2,38p' "$0" | sed 's/^# \{0,1\}//'
}

dry_run="${BLOB_BACKUP_DRY_RUN:-false}"
restore=false
while [[ $# -gt 0 ]]; do
  case "$1" in
    --dry-run) dry_run=true ;;
    --restore) restore=true ;;
    -h|--help) usage; exit 0 ;;
    *) echo "backup-blobs: unknown argument $1" >&2; usage >&2; exit 2 ;;
  esac
  shift
done

fail() { echo "backup-blobs: $*" >&2; exit 1; }

[[ -n "$source_path" ]] || fail "BLOB_BACKUP_SOURCE is not set"
[[ -n "$target_path" ]] || fail "BLOB_BACKUP_TARGET is not set"
[[ "$source_path" != "$target_path" ]] || fail "source and target are the same path; a sync there would delete the backup"

if [[ "$restore" == "true" ]]; then
  swapping="$source_path"
  source_path="$target_path"
  target_path="$swapping"
fi

mkdir -p "$log_dir"
readonly log_file="$log_dir/backup-blobs.log"
# Where rclone itself writes. It differs from log_file only when rclone runs somewhere else.
readonly rclone_log_file="${BLOB_BACKUP_RCLONE_LOG:-$log_file}"

# One run at a time: two overlapping syncs would race on the same target. The loser of the lock
# exits 0 - nothing is wrong, and systemd tries again tomorrow.
exec 9>"$log_dir/backup-blobs.lock"
flock -n 9 || { echo "backup-blobs: another run holds the lock; nothing to do" | tee -a "$log_file"; exit 0; }

# shellcheck disable=SC2206 # rclone_bin is deliberately a command prefix ("rclone", or a container invocation).
readonly -a rclone_cmd=($rclone_bin)

run_rclone() {
  "${rclone_cmd[@]}" "$@"
}

direction="backup"
[[ "$restore" == "true" ]] && direction="RESTORE (second provider back into the primary bucket)"

if [[ "$dry_run" == "true" ]]; then
  echo "backup-blobs: DRY RUN $direction: $source_path -> $target_path ($include_filter)" | tee -a "$log_file"
  run_rclone sync "$source_path" "$target_path" --config "$config" --include "$include_filter" \
    --fast-list --transfers "$transfers" --checkers 8 --dry-run --log-level NOTICE --log-file "$rclone_log_file"
  exit 0
fi

echo "backup-blobs: $(date -u +%Y-%m-%dT%H:%M:%SZ) $direction: $source_path -> $target_path ($include_filter)" | tee -a "$log_file"
run_rclone sync "$source_path" "$target_path" --config "$config" --include "$include_filter" \
  --fast-list --transfers "$transfers" --checkers 8 --retries 3 --low-level-retries 10 \
  --stats 300 --stats-one-line --log-level INFO --log-file "$rclone_log_file"

# The copy is only a backup if it is whole. Compare both sides through the same filter and refuse
# to report success on a difference: a truncated night is exactly the failure this job exists to
# survive, and rclone's exit 0 on a partial sync would otherwise read as a good night.
if [[ "$verify" == "true" ]]; then
  source_size="$(run_rclone size "$source_path" --config "$config" --include "$include_filter" --fast-list --json)"
  target_size="$(run_rclone size "$target_path" --config "$config" --include "$include_filter" --fast-list --json)"
  # count and bytes only; rclone also reports sizeless entries, which are equal on both sides.
  source_count="$(printf '%s' "$source_size" | sed -n 's/.*"count":\([0-9]*\).*/\1/p')"
  target_count="$(printf '%s' "$target_size" | sed -n 's/.*"count":\([0-9]*\).*/\1/p')"
  source_bytes="$(printf '%s' "$source_size" | sed -n 's/.*"bytes":\([0-9]*\).*/\1/p')"
  target_bytes="$(printf '%s' "$target_size" | sed -n 's/.*"bytes":\([0-9]*\).*/\1/p')"
  [[ -n "$source_count" && -n "$target_count" ]] || fail "rclone size reported no count; cannot verify the copy"
  echo "backup-blobs: verified $target_count objects / $target_bytes bytes in the copy against $source_count / $source_bytes in the source" | tee -a "$log_file"
  [[ "$source_count" == "$target_count" && "$source_bytes" == "$target_bytes" ]] || fail "the copy does not match the source (see $log_file)"
fi

echo "backup-blobs: done" | tee -a "$log_file"
